      "lesson": "米国を連邦・大統領制、英国を単一・議院内閣制に分類した。 米国は連邦国家で大統領制。英国は単一国家で議院内閣制。国家構成と執政制度の二軸を分ける。 フランスは単一国家の半大統領制、ロシアは連邦国家の半大統領制として問題集の類型を読む。 問題集の類型では仏は単一・半大統領、露は連邦・半大統領。これは制度分類であり政治的自由の評価とは別。 ドイツの大統領は象徴的役割が中心で、議院内閣制の首相が政治の実権を担う。 米国上院は各州2名、下院は州人口に応じる。上院は高官・最高裁判事人事や条約への同意権を持つ。 人事同意・条約同意は上院の権限であり、下院だけの権限ではない。 英国では下院が直接選挙で選ばれ、非公選の上院に対して下院優越が認められる。 英国は下院優越で、下院多数党の党首が首相となる。上院には世襲貴族等に由来する非公選の構成がある。下院優越の確立は1911年。 フランス大統領は国民が直接選び、首相と併存するが、議会による内閣への不信任もある。 フランスの半大統領制は、大統領の直接選挙と議院内閣制的な責任関係を併せ持つ。 米国は厳格な権力分立で議員兼職・議会解散・通常の不信任はない。弾劾、拒否権、教書を区別する。 日本の両院は公選で、法律案の再可決は衆議院の出席議員の3分の2以上による。 英国の非公選上院とは異なる。米国の人事・条約への同意は上院。日本の法律再可決は総議員でなく出席議員が分母。",
