      "printSection": "N03",
      "lesson": "選挙権が広くても政府批判が抑圧されれば、包括性と自由化の両方が高いとはいえない。 包括性は参加する人の広がり、自由化は抑圧なく政府に反対できる程度。ソ連の形式的普通選挙だけで自由化を高くしない。 日本国憲法下の普通選挙と表現の自由は、参加・異議申立ての両軸を高くする条件になる。 現行日本は包括性と自由化がともに高い類型。19世紀英国のチャーティスト運動期は参加が限定された。 男女普通選挙の普及は20世紀。世界初はニュージーランド1893年、独1919年、米1920年、日本の女性参政権は1945年。 選挙権の拡大に伴い、地域有力者中心の名望家政党から、多数の有権者を組織する大衆政党へ進んだ。 名望家政党→大衆政党の順。選挙権の拡大が組織の変化を促した。 ナチスは1932年の選挙等で議席を拡大し、1933年の首相就任と全権委任法を経て独裁化した。 スターリンの粛清、日本の1940年の大政翼賛会、1980年代の韓国・フィリピンの民主化を別の歴史過程として整理する。 レーニン死後のスターリンによる粛清・農業集団化、近衛の新体制運動、韓国・フィリピンの独裁批判と民主化を混同しない。",
