      "lesson": "日本への攻撃と他国への攻撃を契機とする自衛は分類が異なり、日本が後者を行使するには存立への危険、他に適当な手段がないこと、必要最小限度という要件を満たす必要がある。 自国への攻撃は個別的自衛権、他国への攻撃を契機とするのは集団的自衛権。2014年閣議決定・2015年法制では、密接な関係にある他国への攻撃で日本の存立と国民の生命・自由・幸福追求権が根底から覆される明白な危険、他に適当な手段がないこと、必要最小限度にとどまることを要する。 NATOは集団的自衛権。国連の強制措置は集団安全保障であり、PKOとも別。湾岸戦争後の日本の掃海派遣は政府説明上、集団的自衛権の行使ではない。 1951年は旧安保条約。1960年に新安保へ改定され安保闘争が起きた。新条約は日本の領域内の日本または米国への武力攻撃に共同対処する。 マッカーサーの指示による警察予備隊発足は、自衛隊成立前の1950年である。 警察予備隊1950年→保安隊1952年→自衛隊1954年。GHQが一貫して自衛組織を拒絶したわけではない。 1992年のPKO協力法、対テロ支援、イラク支援、海賊対処は、それぞれ異なる法的根拠を持つ。 PKO協力法でPKO参加が可能となりカンボジア等へ派遣。モザンビークPKOも同法。テロ対策特措法・イラク特措法・海賊対処法による派遣をPKOと一括しない。 イラクへは人道復興支援等で実際に派遣された。ソマリア沖の活動は海賊対処の法制で、PKOではない。 最高裁は安保条約を違憲と判断していない。高度の政治性を理由に司法判断を抑制する統治行為論と関連する。 問題集の歴史的叙述では非核三原則の放棄はなく、総理・国務大臣は全員文民。防衛相だけの憲法上の例外はない。 2014年の三原則は条件を設けて移転を認める枠組み。旧武器輸出三原則からの変化であり、全面禁止と説明しない。後年の運用改定と区別する。 2013年に設置された国家安全保障会議は内閣に置かれ、自衛隊の最高指揮監督権は総理にある。 国家安全保障会議は重要事項を審議。最高指揮監督権を防衛相と取り違えない。1978年・1997年・2015年のガイドラインも日米協力の歴史として整理する。 在日米軍駐留経費の日本側負担を、歴史的には思いやり予算と呼んできた。 通称と条約の安全保障上の義務を区別する。問題集の呼称を現在の全経費の正式名称とみなさない。 掃海派遣1991年→PKO協力法とカンボジア派遣1992年。活動名だけでなく年と法的根拠を照合する。",
