      "lesson": "政治的意見を共有する団体を作る自由は、財産権でなく精神的自由に分類する。 結社の自由は21条。弁護人依頼は人身の自由、財産利用は経済的自由、良好な環境は新しい人権。 最高裁は憲法の人権規定の私人間への直接適用を否定し、当該採用拒否を違憲とはしなかった。 愛媛玉串料訴訟の公金支出は違憲、東大ポポロ事件では学問の自由と大学自治を関連付けた。 愛媛は20条・89条の政教分離違反。学問の自由には大学自治も含まれる。津地鎮祭等の別事件と一律に扱わない。 報道の自由は表現の自由に含まれるが、取材対象のプライバシーと衝突することがある。 21条は通信の秘密と検閲禁止も規定。1999年情報公開法に知る権利という名称は明記されていない。 「石に泳ぐ魚」事件で出版差止めが認められた。表現とプライバシーの調整が必要。 チャタレイ事件はわいせつ文書規定を合憲とし、捜査の通信傍受には裁判官の令状を必要とする。 通信傍受法は1999年。特定秘密保護法は2013年に外交・防衛等の秘密漏えいを規制する制度として制定。両者を同じ法律としない。 自治体計画の審査は思想内容等の表現物への検閲とは異なる。新聞・サイト・小説を行政が発表前に禁ずる例と比較する。 DV防止法の成立2001年と、通信傍受法の成立1999年は、同じ出来事の呼び名ではない。 DV防止法は配偶者等からの暴力への保護・防止。通信傍受法は一定犯罪の捜査に関する令状等の手続。目的と制定年を対応させる。",
