      "lesson": "朝日訴訟と堀木訴訟の最高裁判断を、プログラム規定説と関連付けて学ぶ。 朝日訴訟1967年・堀木訴訟1982年で請求を認めなかった。法的権利説とプログラム規定説の結論を逆にしない。 プログラム規定説の説明では直ちに具体的給付を請求する法的権利としない。国の政治的・道義的責務という説明と区別する。 職業紹介は勤労権、生活保護は生存権、組合加入を理由とする解雇の禁止は団結権に対応する。 ハローワーク等による就業機会、生活保障、不当労働行為の禁止を具体例から分類する。労働基本権は生存権を実質的に支える。 国公立学校の特定宗教教育は政教分離から認められない。社会権と信教の自由を混同しない。 義務教育で授業料だけでなく教科書の無償配布も法制度として行われている。 憲法の義務教育無償と、教科書無償給与の法律を区別しつつ制度として整理する。 勤労の義務は強制労働の根拠ではない。公務員の労働基本権には制約があり、人事院勧告等の代償措置がある。",
