      "lesson": "在外邦人の選挙権を比例代表に限る旧規定を、最高裁は2005年に違憲とした。 海外居住の日本国民の国政参加の保障。外国籍の永住者の国政選挙権とは別問題。 女性参政権は1945年に法制化され、1946年の選挙で行使されたので、1947年の憲法施行後に初めて認められたわけではない。 法制化・初行使・憲法施行を年代で区別する。男女共同参画法で国会議席が男女同数になったわけでもない。 自治体の首長の直接選挙は憲法に根拠があり、衆議院選挙権は日本国民18歳以上、参議院の被選挙権は日本国民30歳以上である。 永住外国人に国政選挙権はない。成人年齢・投票年齢と被選挙権年齢を区別する。 条約は国会承認。国民審査は最高裁裁判官の罷免の可否で、選挙による任命ではない。 国家賠償請求は国または地方公共団体への損害回復を求める制度で、情報公開法は行政情報の公開を扱う。 国家賠償と刑事補償は別。情報公開法をプライバシーの積極的実現だけの法律としない。 裁判を受ける権利は憲法32条、国家賠償請求権は17条、刑事補償は40条であり、信教の自由や財産権と分類が異なる。 請求権は権利救済等を国家へ求める。財産権29条は経済的自由、信教20条は精神的自由、生存25条は社会権。",
