      "lesson": "教育・労働・生活等を扱うA規約と、意見を持つ自由等を扱うB規約を区別する。 Aは社会権規約、Bは自由権規約。自由権は国家からの自由、社会権は国家による生活保障と関連する。 自由権規約の第一選択議定書は、国内救済を尽くした個人の通報制度を扱う。 B規約本体の意見の自由の規定と、第一選択議定書の個人通報を条文内容で識別する。日本は同議定書未批准。 世界人権宣言は宣言、国際人権規約は法的拘束力を持つ条約。採択年と日本の批准1979年を分ける。 女子差別撤廃条約への対応は国籍法と雇用機会均等法、子どもの権利条約は18歳未満の子を権利主体とすることに関連する。 女子差別撤廃条約採択1979年・日本批准1985年。子どもの権利条約採択1989年・日本批准1994年。 採択前に批准できない。1965年の人種差別撤廃条約、1979年の女子差別撤廃条約、1989年の子どもの権利条約を時系列で整理する。 国際人権規約への日本の批准は1979年で、A規約の一部事項の留保とB規約議定書の未批准は別の状態である。 未批准と一部留保を区別する。公務員争議権や公休日報酬等の留保という問題集の説明を、規約全体の未批准に置き換えない。",
