      "lesson": "帝国議会には非公選の貴族院があり、現行国会は両院公選で首相を指名する。 旧憲法には緊急勅令があり、現行憲法にない。現行国会議員は全国民の代表であり、選出団体による命令委任・国民によるリコールは制度化されていない。 日銀総裁などの国会同意人事には衆議院の優越はない。定数は法律で変更できる。常会は毎年1月召集・150日。党首討論は1999年の国会改革と関連。 議員除名は弾劾裁判所でなく当該議院の出席議員の3分の2以上で決める。 弾劾裁判所は裁判官の罷免。議員の歳費・不逮捕・免責特権を区別する。不逮捕は会期中が原則で現行犯等の例外、免責は院内の発言・表決について院外で責任を問わない。 日本は委員会中心主義で、予算の公聴会は必須だが法律案一般の公聴会は必須ではない。 帝国議会は本会議中心。常任委員会と特定案件の特別委員会があり、特別委員会は同一会期中でも案件終了により終了し得る。 予算を伴わない議員立法の発議は衆20人・参10人、予算を伴えば衆50人・参20人以上の賛成を要する。 人数を分ける。原則は委員会審査→本会議。法律・政令には主任国務大臣の署名と首相の連署が必要。 法律案はどちらの院からでもよい。予算は衆先議。会計検査院は財政支出を事後検査する。地方特別法は住民投票の過半数であって首長の同意ではない。 憲法審査会は改憲等の調査・審査。違憲審査は下級裁判所にもある。下級裁判官は最高裁指名名簿から内閣任命。国政調査権は各院にあり、閣僚の出席要求に応じる義務と区別する。 1999年国会改革は政府委員制度を廃止して官僚が大臣の代わりに答える仕組みを改めた。 副大臣・大臣政務官と党首討論を導入。大臣は議席の有無にかかわらず両院に出席・発言でき、要求があれば出席義務がある。 予算は衆議院先議だが法律案は参議院から審議してもよく、内閣提出法律案の成立割合が議員提出より高い時期もある。 問題集の1990年代等の資料では政府提出の成立割合が高い。特定時期の統計を全時代の必然にしない。国費支出の国会承認と会計検査の事後検査も別。",
