      "lesson": "最高裁長官は内閣指名・天皇任命、他の最高裁裁判官は内閣任命で、国会の同意は必要ない。 下級裁判官は最高裁指名名簿から内閣任命。任期10年・再任可は憲法80条。最高裁は長官と14名で構成。 裁判官の身分保障は司法の独立、裁判公開は公正の確保、三審制は慎重な審理と対応する。 制度名を知るだけでなく目的を対応させる。行政機関による裁判官の懲戒は禁じられ、良心と憲法・法律にのみ拘束される。 司法は独立。最高裁は訴訟手続・弁護士・内部規律・司法事務の規則を国会承認なしで定める。国会の裁判官への関与は弾劾制度など。 身分保障があっても、心身の故障に関する裁判、弾劾、最高裁裁判官の国民審査による罷免はあり得る。 弾劾裁判所は両院各7人の議員で構成。犯罪被害者参加制度は2008年開始で対象事件に被害者等が参加可能。 裁判の対審は一定の例外で非公開にできるが、判決は公開し、政治犯罪・出版犯罪・基本的人権の事件の対審は常に公開する。 82条の全員一致による公の秩序・善良の風俗の例外と、公開が必要な事件を分ける。「すべての刑事裁判は常に全面公開」とはしない。 分母は投票者。任命後初の衆院総選挙、その後10年経過後初の総選挙。×以外の記入をせず白紙は罷免意思なしとして扱う。公務員選定罷免権の具体化。",
