      "title": "違憲審査の立場と判例の結論",
      "unit": "司法",
      "importance": "A",
      "source": "問題集p.57-58・出版社解説の該当項目（原本非公開）",
      "printSection": "N25",
      "lesson": "少数者の人権保障を重視すれば司法積極主義、国会の選挙に基づく正統性を尊重すれば司法消極主義の根拠になる。 国政調査権に基づく国会の判断能力、政治部門の責任も消極主義の根拠。表現の過度な制約への救済は積極主義側。 事件から独立は抽象的審査。日本は付随的。長沼の自衛隊違憲は札幌地裁で、最高裁の判断ではない。最高裁は全逓名古屋中郵事件で国家公務員争議禁止を合憲とした。 津地鎮祭は合憲、愛媛玉串料と空知太神社への土地無償提供は違憲として整理する。 津1977年、愛媛1997年、空知太2010年。宗教との関わりを一律に違憲・合憲としない。目的・効果等を踏まえた各結論を区別。 環境権の独立承認と、公害の損害賠償・差止めが認められた事例の有無は別に判断する。 日照侵害の救済や尼崎道路公害の差止め事例がある。大阪空港の差止めは下級審で認容、最高裁は1981年に退けた。どの審級の判断かを区別する。",
