      "lesson": "自治事務は都市計画や飲食店許可、法定受託事務は国政選挙・戸籍・旅券などに対応する。 分類は法律に基づき憲法の列挙ではない。法定受託は本来国等が果たす役割を法律で地方に任せるもので、地方の仕事を国に委託することではない。自治事務への国の関与はより限定的。 1999年地方分権一括法は機関委任事務を廃止し、国と地方を上下から対等・協力へ改めることを目指した。 自主課税の法定外税拡充は団体自治、住民の解職請求は住民自治。地方税法にない法定外目的税は用途を特定し得る。 条例は法律の範囲内。指定管理者制度2003年で公共施設の管理を民間等に任せられる。法定外目的税の設置は法の手続・要件がある。 地方税は自主財源、地方交付税は依存・一般財源、国庫支出金は依存・特定財源と二軸で整理する。 交付税は財政力が強い自治体が弱い自治体へ直接送る税ではなく国から配分。国庫支出金は事業ごとに用途指定。地方債も依存財源。 三位一体改革は税源移譲・国庫補助負担金の削減・地方交付税の見直しを柱とし、地方債への国の関与の完全廃止は含まない。 小泉内閣期の改革。相続税は国税のまま。地方債は2006年から原則協議へ変化したが、許可等を要する場合もあり一律無関与ではない。 地方公営企業の職員は団結・団体交渉・労働協約締結ができるが争議行為は禁止され、自治体職員の要件を一律に当該自治体居住・日本国籍とするのは誤りである。 公権力行使等の職には国籍の制約がある。一般の地方公務員の労働基本権制限と、地方公営企業の労働権を区別する。",
