      "lesson": "条例制定改廃は首長へ、事務監査は監査委員へ、議会解散と議員・首長解職は選挙管理委員会へ請求する。 制定改廃と監査は有権者1/50以上。解散・解職は原則1/3だが40万・80万超の部分に緩和。宛先と署名、後続手続を別々に確認する。 副知事や監査委員等の解職は首長へ請求し、議会が総議員2/3以上出席・出席3/4以上同意で議決する。 住民投票になる首長・議員解職と、議会判断になる役員解職を区別する。 条例は議会審議議決、監査は監査実施と結果公表。解散・首長議員解職は投票の過半数で効力を生じる。 地方自治法1947年→革新自治体の広がり1960〜70年代→平成の大合併→大阪の特別区設置住民投票2015・2020年の順になる。 平成合併で市町村1700台となったのは2000年代。大阪の二度の投票はいずれも反対多数。条例投票では外国人投票例があり、情報公開条例も国法1999年に先行。",
