      "lesson": "制限選挙の名望家政党、普通選挙の大衆政党、階級対立の弱まりと包括政党という流れを区別する。 包括政党は1960年代の脱イデオロギー化とも関連。政党は政権獲得を目指す。憲法に政党の明文規定はなく、党議拘束も法律で一律禁止されていない。 明治憲法下でも1898年の大隈内閣や憲政の常道に政党内閣があり、戦後初選挙1946年に自民党が成立したわけではない。 1932年五・一五事件で政党内閣が途絶。1955年に社会党再統一と自由党・日本民主党の保守合同。自民と社会が交互に政権を取る二大政党制ではなく自民優位。 野党多党化は主に1960年代、保革伯仲は1970年代で、1980年代には自民党が勢力を回復した。 新自由クラブ1976年、新生党・新党さきがけ1993年等の離党新党があった。ロッキード1976年・リクルート1988年等の構造汚職を政官財の癒着と関連付ける。 1993年の宮澤内閣不信任と総選挙後に非自民の細川連立政権ができ、1994年に衆院選挙制度が改正された。 日本新党1992年、新生党・さきがけ1993年。中選挙区では同党の複数候補が争った。自民は1994年に社会・さきがけとの連立で復帰。無党派知事は官僚支配を強める目的ではなく改革で対立する場合もあった。 2005年の総選挙後は小泉政権の郵政民営化、2009年の総選挙後は鳩山政権への交代と対応する。 第44回2005年は自民、第45回2009年は民主が300超という図の特徴から時点を特定できる。2009年は民主・社民・国民新の連立。1993年の細川と混同しない。 政党・連立の現在は時点依存。ここでは1993、2005、2009など設問で指定した歴史の判断を練習し、旧解説の「現在」を2026年へ移し替えない。",
