      "printSection": "N30",
      "lesson": "1998年NPO法は非営利活動団体の法人格取得等を支え、利益集団は政府等に働きかける。 政権獲得を目指す政党と区別。米国のロビイスト登録を日本にも同じ国会登録制度があるとしない。 無党派層とは特定の支持政党を持たない有権者であり、必ず無所属にしか投票しない人ではない。 政治への無関心とは同義ではない。政党は特定団体の利益だけでなく社会全体の利益を集約・調整する役割を持つ。 政党助成の対象は国会議員5人以上、または国会議員を有し所定の国政選挙で得票率2%以上等の条件を満たす政治団体で、得票だけで議員ゼロでも対象になるわけではない。 政党助成法1994年。後者の選挙は直近の衆院総選挙、直近またはその前の参院通常選挙で、選挙区または比例の全国得票率をみる。企業・労組等の寄付先は原則政党・政治資金団体に限定され、政治家個人やその資金管理団体への献金と区別する。 事前運動は禁止。2013年に一定条件下でネット選挙運動解禁。戸別訪問は禁じられ、期日前投票は投票日当日に投票できない事情等に対応する。",
