      "id": "N32",
      "title": "行政国家と官僚制の統制",
      "unit": "政治参加",
      "importance": "A",
      "source": "問題集p.73-76・出版社解説の該当項目（原本非公開）",
      "printSection": "N32",
      "lesson": "福祉・経済政策の拡大による行政国家では、行政裁量・委任立法・専門官僚が増え、夜警国家の小さな政府と異なる。 市場の失敗等への対応で国の仕事が治安・国防以外へ拡大。行政不介入への回帰が行政国家の定義ではない。 官僚統制という目的なら、国会の国政調査や政治家による答弁、情報公開やオンブズマンが対応する。 政府委員の答弁拡大は官僚活用でも統制強化とは異なる。首相公選制は強化策としての提案であり現行制度ではない。 セクショナリズムは部門の権限保持による縦割り、形式主義は手続の自己目的化、秘密主義は情報を隠す傾向を指す。 法の機械的適用等は法律万能主義。天下りは関係業界等への退職後の再就職。族議員は特定分野の官庁・業界に強い影響を持つ議員。 許認可等の手続の公正・透明化が目的。行政指導は任意の協力に基づき不利益取扱いを禁ずる等の規律がある。行政評価とは別。 国家公務員給与の勧告は人事院、幹部人事管理は内閣人事局2014年、事務次官は官僚の役職に対応する。 人事院は廃止されていない。自衛官には争議権はない。一般職には団結・交渉が認められるが労働協約締結権等の制約がある。公務員は現行憲法15条の全体の奉仕者。 オンブズマンは行政苦情を中立的に調べ改善を勧告し、監査委員は自治体の監査結果を公表・議会首長へ報告する。 情報公開法は国の行政文書、自治体は条例。監査結果の報告先を国会としない。行政文書請求・監査・権利侵害への抗議と、人気の高い候補への追随を区別する。 国政調査と行政訴訟は法制度に基づく行政外部の統制、人事院と自治体監査委員は法制度に基づく内部統制に分類できる。 新聞報道は制度外・外部、同僚の反応は制度外・内部。内外と法制度の有無の二軸を別々に当てはめる。",
