      "lesson": "1980年代の三公社民営化は電電・専売・国鉄で、道路公団は2005年の分割民営化である。 道路と国鉄を同じ年にしない。郵政省→郵政事業庁→日本郵政公社2003年→郵政民営化2007年。郵便・貯金・簡保の三事業を対象とする。 構造改革特区は2002年法・2003年開始、国家戦略特区は2013年法の制度である。 規制緩和の区域・分野を限定する仕組み。1980年代から国家戦略特区があったという説明は誤り。 独立行政法人制度は2001年開始で政策企画と実施の分離・効率化を図り、日本住宅公団等の再編でURが2004年にできた。 特殊法人制度そのものは以前からある。NHKは特殊法人としての公共放送で、民放と同一の地位になったわけではない。電力・ガスはもとから株式会社であった。 第三セクターは公益的な事業を担うが、破綻時の公金投入や行政の責任が問題になる場合もある。 第一セクターの国・自治体と第二セクターの民間の共同出資。行政手続法の透明化、独立行政法人の効率化と目的を区別する。",
