      "lesson": "マスメディアは世論形成や権力監視から第四の権力と呼ばれ、世論調査や予測報道が投票行動を変えることもある。 アナウンスメント効果。質問の文言・順番等で同じ話題でも調査結果は変わり得る。戦前の報道統制や戦後GHQ検閲があり、常に政治権力から自由だったとはいえない。 新聞は社説で自社の見解を示し、被疑者の実名報道や首相動静も行われ、記者クラブには排他性の批判がある。 フリー記者への開放例もあるが、すべての機関で全面的な排除が解消したとはいえない。犯罪報道の判断は各社で異なり得る。 ネットの表現にも名誉毀損やプライバシーの規律が及び、テレビにも表現の自由が保障される。 媒体だけで自由保障・責任がなくなるわけではない。青少年のフィルタリングは事業者の提供義務等と保護者の責務を区別し、保護者への無例外の利用義務とはしない。 不開示の適法性は裁判で争え、開示を命じる判断もあり得る。行政文書の情報公開法と自己情報の開示訂正を扱う個人情報保護法を区別する。 請願は憲法16条にあり、法律の制定廃止等の希望を平穏に申し立てられる。 政治資金には収支報告等の規制がある。世論調査・大衆運動・利益集団は意思反映に関わり、族議員は特定政策分野と結び付く。合意を重んじる型は多数者支配型と区別し、大衆迎合は直接民主制と同義ではない。",
