      "printSection": "N35",
      "lesson": "デジタルデバイドは情報格差、サイバーテロは情報システム等への攻撃、SOHOは小規模事務所や在宅の働き方に対応する。 格差を単に情報の悪用の危険という意味にしない。ユビキタスは誰でもいつでもどこでもネットにつながる環境という概念。 電子政府は国・自治体の行政手続等の電子化を目的とし、外国との外交交渉だけの高速化ではない。 コーポレートガバナンスは企業統治。不正アクセス防止だけの技術ではなく経営監視・適切な運営の仕組み。 電子商取引は携帯端末による個人の商品購入も含み、個人情報保護法は民間のデータ利用にも規律を設ける。 ネットでの商品・サービス取引という意味。情報利活用の促進と無規制は別。ドローンには産業利用と悪用の両面がある。 マイナンバーは税・社会保障等の情報管理に関わり、他人のIDやパスワードの不正使用等には不正アクセス禁止法の規制がある。 1999年不正アクセス禁止法。行政だけが個人情報規律の対象という説明は誤り。情報漏えい等の懸念と制度目的をともに整理する。",
