      "unit": "政治参加",
      "importance": "A",
      "source": "問題集p.78-79・出版社解説の該当項目（原本非公開）",
      "printSection": "N36",
      "lesson": "NPOの非営利は有給職員を雇えない意味ではなく、法人格はNPO法に基づいて取得できる。 1998年法。特定政党の支持を主目的とする団体ではなく、企業民営化でだけ生まれるものでもない。 NPOは自治体との協働や指定を受けた介護サービスを担い得て、阪神・淡路大震災1995年はボランティア活動の重要性を広めた。 有給職員も可能。サービス提供と営利分配を区別する。1995年をボランティア元年と呼ぶ。 市民運動は1970年前後の公害対策に影響し、沖縄米軍基地投票1996年や御嵩の廃棄物施設投票1997年等が行われた。 徳島の可動堰投票2000年もある。条例投票には法的拘束力がなくても政治的影響があり、反対結果で事業中止の例もある。 独自の自治、伝統文化・言語教育、伝統的な営みへの配慮が承認の例。公用語への同化を権利付与の条件とする例は異なる。 住民投票は特定争点の意思を直接示し、二元代表制は代表者間の慎重な議論を期待する仕組みとして補完し得る。 直接投票の意義、代表による議論の意義、条例投票の法的拘束力の限界を別々に述べる。",
